INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رمد:fayyumi_misbah_munir', 'رمد', 'd5911e52ff9c9dd47cda3fa16b', 'رَمِدَتْ الْعَيْنُ رَمَدًا مِنْ بَابِ تَعِبَ فَالرَّجُلُ أَرْمَدُ', 'the eye became sore', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_7ac1f128af756cf6', '1220', NULL, 'blk_msb_a70abb4c2aa15aa8', 0, NULL, 'Marker: head gloss. Reading: sore eyes. Differs from the main reading (ash, ash colour).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رمد:zabidi_taj_arus', 'رمد', 'd5911e52ff9c9dd47cda3fa16b', '(الرِّمْدِدَاءُ، بِالْكَسْرِ) ممدوداً: الرَّمَاد.)', 'ash', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_f3b546f8ae4926d9', '115', 8, 'blk_taj_47fddf67711a8587', 0, NULL, 'Marker: Qāmūs gloss. Reading: ash. Primary: ash, ash colour — 4 of 7 books (al-Jawharī blk_sih_2665255861fc8042; Ibn Fāris blk_mqy_62d357c4949c8a52; al-Rāghib blk_mfr_edf4ae26138db274; Tāj blk_taj_47fddf67711a8587). Other readings: sore eyes: Ibn Fāris, Lisān, al-Miṣbāḥ · perishing: Lane · fast running: Ibn Fāris.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رمد:lane_lexicon', 'رمد', 'd5911e52ff9c9dd47cda3fa16b', 'They (a people, or party,) perished: (Sh, T, M, A, L:) or became like رَمَاد [or ashes]', 'they perished, or became like ashes', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_ae006f7761aab856', '1153', NULL, 'blk_lane_cf0b246ea35f8786', 0, NULL, 'Marker: first sense A1. Reading: perishing. Differs from the main reading (ash, ash colour).', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: sore eyes, ash, ash colour, fast running.', updated_at = datetime('now') WHERE id = 'ASL:رمد:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:رمد:zabidi_taj_arus' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'رمد' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:رمد:zabidi_taj_arus' AND status <> 'rejected');
